      "code": "import math\n\ndef build(p):\n    # A round core with eight fused peripheral grip bumps.\n    part = cq.Workplane('XY').circle(p.body_radius).extrude(p.body_height)\n    for i in range(int(p.grip_count)):\n        a = 2.0 * math.pi * i / p.grip_count\n        x = p.grip_center_radius * math.cos(a)\n        y = p.grip_center_radius * math.sin(a)\n        bump = cq.Workplane('XY').center(x, y).circle(p.grip_radius).extrude(p.body_height)\n        part = part.union(bump)\n\n    pocket_depth = p.nut_height + p.pocket_recess\n    floor_z = p.body_height - pocket_depth\n\n    # Hexagonal nut well, open at the top. CadQuery polygon diameter is\n    # corner-to-corner, so convert across-flats dimensions to that diameter.\n    hex_d = p.pocket_af / math.cos(math.pi / 6.0)\n    hex_cut = (cq.Workplane('XY').workplane(offset=floor_z)\n               .polygon(6, hex_d).extrude(pocket_depth + 0.02))\n    part = part.cut(hex_cut)\n\n    # Short, wider entrance eases alignment of the nut while leaving the\n    # lower pocket close-fitting for retention.\n    mouth_d = p.mouth_af / math.cos(math.pi / 6.0)\n    mouth_z = p.body_height - p.mouth_depth\n    mouth_cut = (cq.Workplane('XY').workplane(offset=mouth_z)\n                 .polygon(6, mouth_d).extrude(p.mouth_depth + 0.02))\n    part = part.cut(mouth_cut)\n\n    # Axial bolt passage through the pocket floor to the opposite face.\n    bore = cq.Workplane('XY').circle(p.bolt_passage_d / 2.0).extrude(floor_z + 0.02)\n    part = part.cut(bore)\n    return part",
